def template_path():
    """Ghi mẫu ra file tạm (một lần) và trả đường dẫn."""
    path = os.path.join(tempfile.gettempdir(), "hongthien_able_dccn_mau.xlsx")
    raw = base64.b64decode(ABLE_DCCN_B64)
    try:
        if not (os.path.isfile(path) and os.path.getsize(path) == len(raw)):
            with open(path, "wb") as f:
                f.write(raw)
    except OSError:
        path = os.path.join(tempfile.mkdtemp(), "able_dccn.xlsx")
        with open(path, "wb") as f:
            f.write(raw)
    return path
